package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.ReviewService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/products/{productId}/reviews") public class ReviewController {private final ReviewService s;public ReviewController(ReviewService s){this.s=s;} @GetMapping public List<ReviewResponse> all(@PathVariable UUID productId){return s.all(productId);} @PostMapping public ReviewResponse add(@PathVariable UUID productId,@Valid @RequestBody ReviewRequest r,Authentication a){return s.add(productId,r,a);}}